import {categories,exampleRequest} from './data.mjs';
import {money,validate,matchSuppliers,parseLocally,validateOffer,canAccept} from './matching.mjs';
import {load,persist,reset,uid} from './store.mjs';
let db=load(),view='discover',request=exampleRequest(),results=null,selected=new Set(),supplierId='c1',aiEnabled=false;
const main=document.getElementById('main'),modal=document.getElementById('modal'),$=id=>document.getElementById(id);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const opts=(arr,current)=>arr.map(v=>`<option ${v===current?'selected':''}>${esc(v)}</option>`).join('');
const badge=status=>`<span class="badge ${status==='Approved'?'approved':status==='Quoted'?'quoted':''}">${esc(status)}</span>`;
function save(){if(!persist(db))toast('Browser storage is unavailable. Changes last only until you reload.');$('request-count').textContent=db.requests.length;}
let toastTimer;function toast(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4500);}
function open(title,body){$('modal-title').textContent=title;$('modal-body').innerHTML=body;modal.showModal();}
$('close-modal').onclick=()=>modal.close();modal.addEventListener('click',ev=>{if(ev.target===modal)modal.close();});
document.querySelector('.brand').onclick=ev=>{ev.preventDefault();navigate('discover');};
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));
function navigate(next){view=next;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));render();}
$('reset-demo').onclick=()=>{open('Reset sample workspace?',`<p>This removes saved demo requests, offers, and pricing changes from this browser.</p><div class="dialogactions"><button data-action="close">Cancel</button><button class="primary" id="confirm-reset">Reset demo</button></div>`);$('confirm-reset').onclick=()=>{db=reset();request=exampleRequest();results=null;selected.clear();save();modal.close();navigate('discover');toast('Sample workspace reset.');};};
document.addEventListener('click',ev=>{if(ev.target.closest('[data-action="close"]'))modal.close();});
function render(){save();if(view==='discover')renderDiscover();if(view==='requests')renderRequests();if(view==='supplier')renderSupplier();}
function readForm(){const form=$('request-form');const f=new FormData(form);request={...request,brief:f.get('brief'),quantity:Number(f.get('quantity')),location:f.get('location'),date:f.get('date'),budget:f.get('budget'),notes:f.get('notes'),specs:Object.fromEntries(categories[request.category].fields.map(([key])=>[key,f.get(key)]))};return request;}
function renderDiscover(){const cat=categories[request.category];main.innerHTML=`<div class="eyebrow">LOCAL SUPPLIERS · CEBU</div><h1>Your requirements. The right suppliers.</h1><p class="muted">Find a supplier who offers what you actually need.</p><div class="categories" aria-label="Service categories">${Object.entries(categories).map(([id,c])=>`<button class="category" data-category="${id}" aria-pressed="${request.category===id}"><span class="category-icon" aria-hidden="true">${c.icon}</span>${c.name}</button>`).join('')}</div><div class="workspace"><section class="panel brief-panel"><h2>What are you looking for?</h2><p class="small">${cat.description}</p><form id="request-form"><div class="field"><label for="brief">Describe your request</label><textarea id="brief" name="brief" maxlength="6000" required>${esc(request.brief)}</textarea></div><div class="row"><button type="button" id="extract" class="subtle">${aiEnabled?'Extract with AI':'Extract sample details'}</button><button type="button" id="example" class="textbutton">Use example</button></div><p class="helper" id="extract-mode">${aiEnabled?'Connected AI extraction. Review all fields before comparing.':'Local pattern helper active. AI is optional; see README.'}</p><div id="extraction-feedback" class="helper-state" aria-live="polite"></div><hr class="separator"><div class="twocol"><div class="field"><label for="quantity">Quantity · ${cat.unit}</label><input id="quantity" name="quantity" type="number" min="1" max="10000" step="1" required value="${request.quantity}"></div><div class="field"><label for="budget">Budget cap · optional ₱</label><input id="budget" name="budget" type="number" min="0.01" step="0.01" placeholder="No limit" value="${esc(request.budget)}"></div></div>${cat.fields.map(([key,label,options])=>`<div class="field"><label for="spec-${key}">${label} · required</label><select id="spec-${key}" name="${key}" required><option value="">Choose an option</option>${opts(options,request.specs[key])}</select></div>`).join('')}<div class="twocol"><div class="field"><label for="location">Location</label><select id="location" name="location">${opts(['Cebu City','Mandaue City'],request.location)}</select></div><div class="field"><label for="date">Needed on</label><input id="date" name="date" type="date" required value="${esc(request.date)}"></div></div><div class="field"><label for="notes">Other requirements</label><input id="notes" name="notes" maxlength="1000" value="${esc(request.notes)}" placeholder="Dietary counts, colors, access, delivery time…"></div><p class="helper">Extra requirements and the date need supplier confirmation. Prices use the sample catalog as configured; custom variations require review.</p><div id="form-error" class="error" role="alert"></div><button class="primary full" type="submit">Find matching suppliers →</button></form></section><section><div class="resulthead"><div><h2 id="result-title">Potential suppliers</h2><span class="small">Catalog estimates · Sorted by total cost</span></div><button id="compare" disabled>Compare (0)</button></div><div id="results"></div></section></div>`;
main.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{request=exampleRequest(b.dataset.category);results=null;selected.clear();renderDiscover();});$('example').onclick=()=>{request=exampleRequest(request.category);results=null;selected.clear();renderDiscover();toast('Example loaded. Review the selected specifications.');};$('request-form').onsubmit=ev=>{ev.preventDefault();readForm();const errors=validate(request);$('form-error').textContent=errors.join(' ');if(errors.length)return;results=matchSuppliers(request,db.suppliers);selected.clear();drawResults();};$('extract').onclick=extract;$('compare').onclick=compare;results=matchSuppliers(request,db.suppliers);drawResults();
$('request-form').addEventListener('input',()=>{results=null;selected.clear();$('compare').disabled=true;$('compare').textContent='Compare (0)';$('result-title').textContent='Request changed';$('results').innerHTML='<div class="empty"><h3>Refresh your matches</h3><p>Choose Find matching suppliers to apply your changes.</p></div>';});}
function drawResults(){if(!results)return;const cat=categories[request.category];$('result-title').textContent=results.matches.length+' potential supplier'+(results.matches.length===1?'':'s');$('results').innerHTML=`<div class="result-summary">${esc(request.quantity)} ${cat.unit} · ${esc(request.location)} · ${esc(request.date)}<br>Availability, extra requirements, and final price are unconfirmed.</div><div class="supplier-grid">${results.matches.map(m=>`<article class="supplier-card"><div class="supplier-head"><div class="supplier-logo">${m.supplier.initials}</div><div><h3>${m.supplier.name}</h3><span class="small">Serves ${esc(request.location)}</span></div></div><span class="match-label">Listed specifications match</span><div class="supplier-body"><div class="price">${money(m.total)}</div><div class="small">Estimated total${m.deposit?' · deposit separate':''}</div><ul class="details">${m.supplier.inclusions.map(t=>'<li>'+esc(t)+'</li>').join('')}</ul><div class="confirm-note">${esc(m.supplier.notes)}${m.deposit?'<br>Refundable deposit: '+money(m.deposit):''}</div></div><button class="primary" data-request="${m.supplier.id}">Request final quote</button><label class="check"><input type="checkbox" data-compare="${m.supplier.id}" ${selected.has(m.supplier.id)?'checked':''}>Add to comparison</label><button class="textbutton" data-breakdown="${m.supplier.id}">View price breakdown</button></article>`).join('')}</div>${!results.matches.length?'<div class="empty"><h3>No exact matches</h3><p>Try another category, increase your budget, or revise a requirement. We won’t silently replace your specifications.</p></div>':''}<details class="excluded"><summary>${results.excluded.length} supplier(s) excluded · See why</summary>${results.excluded.map(x=>'<p><strong>'+esc(x.supplier.name)+'</strong><br>'+x.reasons.map(esc).join(' · ')+'</p>').join('')}</details>`;
$('results').querySelectorAll('[data-compare]').forEach(cb=>cb.onchange=()=>{cb.checked?selected.add(cb.dataset.compare):selected.delete(cb.dataset.compare);$('compare').textContent='Compare ('+selected.size+')';$('compare').disabled=selected.size<2;});$('results').querySelectorAll('[data-request]').forEach(b=>b.onclick=()=>requestQuote(b.dataset.request));$('results').querySelectorAll('[data-breakdown]').forEach(b=>b.onclick=()=>{const m=results.matches.find(x=>x.supplier.id===b.dataset.breakdown);open(m.supplier.name+' · estimate',breakdown(m)+`<p class="small">${esc(m.supplier.notes)} All listed sample rates are tax-inclusive; no extra tax is added. Supplier must confirm the final offer.</p><div class="dialogactions"><button data-action="close">Close</button></div>`);});}
function breakdown(m){return `<div class="tablewrap"><table><thead><tr><th>Item</th><th>Qty</th><th>Unit</th><th class="align-right">Amount</th></tr></thead><tbody>${m.lines.map(l=>`<tr><td>${esc(l.label)}</td><td>${l.quantity}</td><td class="money">${money(l.unit)}</td><td class="align-right money">${money(l.amount)}</td></tr>`).join('')}<tr class="total-row"><td colspan="3">Estimated service total</td><td class="align-right money">${money(m.total)}</td></tr>${m.deposit?`<tr><td colspan="3">Refundable deposit · separate</td><td class="align-right money">${money(m.deposit)}</td></tr><tr><td colspan="3">Total cash needed incl. deposit</td><td class="align-right money">${money(m.total+m.deposit)}</td></tr>`:''}</tbody></table></div>`;}
function compare(){const list=results.matches.filter(x=>selected.has(x.supplier.id));open('Compare your shortlist',`<div class="tablewrap"><table><thead><tr><th>Compare</th>${list.map(m=>'<th>'+m.supplier.name+'</th>').join('')}</tr></thead><tbody>${[['Estimated total',m=>money(m.total)],['Included',m=>m.supplier.inclusions.join('; ')],['Deposit',m=>m.deposit?money(m.deposit)+' refundable':'None listed'],['Needs confirmation',m=>m.supplier.notes]].map(([label,fn])=>'<tr><th>'+label+'</th>'+list.map(m=>'<td>'+esc(fn(m))+'</td>').join('')+'</tr>').join('')}</tbody></table></div><div class="dialogactions"><button data-action="close">Back to results</button></div>`);}
async function extract(){readForm();const b=$('extract');b.disabled=true;b.textContent='Reading request…';$('extraction-feedback').textContent='';try{let data;if(aiEnabled){const response=await fetch('/api/extract',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text:request.brief,category:request.category}),signal:AbortSignal.timeout(45000)});data=await response.json();if(!response.ok)throw new Error(data.error||'AI request failed');}else data=parseLocally(request.brief,request.category);const cat=categories[request.category];request.specs={};for(const [key,,options]of cat.fields){const v=data.specs?.[key];if(options.includes(v))request.specs[key]=v;}if(Number.isInteger(data.quantity)&&data.quantity>0&&data.quantity<=10000)request.quantity=data.quantity;if(['Cebu City','Mandaue City'].includes(data.location))request.location=data.location;if(Number.isFinite(data.budget)&&data.budget>0)request.budget=data.budget;results=null;renderDiscover();const missing=cat.fields.filter(([k])=>!request.specs[k]).map(([,label])=>label.toLowerCase());$('extraction-feedback').textContent=(aiEnabled?'AI draft ready. ':'Local extraction ready. ')+(missing.length?'Please confirm: '+missing.join(', ')+'.':'Review the extracted options before comparing.')+' Date, quantity, dietary counts, colors, and special instructions still need your review.';if(Array.isArray(data.unresolved)&&data.unresolved.length){const p=document.createElement('p');p.textContent=data.unresolved.slice(0,6).join(' ');$('extraction-feedback').append(p);}}catch(err){$('extraction-feedback').textContent='Could not extract details: '+err.message+'. Your inquiry is preserved. Enter the fields manually.';}finally{if($('extract')){$('extract').disabled=false;$('extract').textContent=aiEnabled?'Extract with AI':'Extract sample details';}}}
function requestQuote(sid){const supplier=db.suppliers.find(s=>s.id===sid);open('Request a confirmed quote',`<p><strong>${esc(supplier.name)}</strong></p><p class="small">Your requirements and inquiry will be copied into a saved demo request. Switch to Supplier desk to respond.</p><form id="send-form"><div class="field"><label for="buyer-name">Your name</label><input id="buyer-name" required maxlength="100" value="${esc(request.customer)}"></div><div class="field"><label for="buyer-contact">Contact · optional for demo</label><input id="buyer-contact" maxlength="150" value="${esc(request.contact)}" placeholder="Email or mobile number"></div><div class="dialogactions"><button type="button" data-action="close">Cancel</button><button class="primary">Create demo request</button></div></form>`);$('send-form').onsubmit=ev=>{ev.preventDefault();request.customer=$('buyer-name').value.trim();if(!request.customer)return;request.contact=$('buyer-contact').value.trim();const snapshot=structuredClone(request);const key=JSON.stringify({...snapshot,customer:request.customer});let saved=db.requests.find(q=>q.key===key);if(saved&&db.offers.some(o=>o.requestId===saved.id&&o.supplierId===sid)){toast('This supplier already has this request. See My requests.');modal.close();return;}if(!saved){saved={...snapshot,id:uid(),key,created:new Date().toISOString()};db.requests.unshift(saved);}const m=results.matches.find(x=>x.supplier.id===sid);db.offers.unshift({id:uid(),requestId:saved.id,supplierId:sid,status:'Requested',version:0,history:[],estimate:m.total,deposit:m.deposit,total:null,terms:'',expires:''});supplierId=sid;save();modal.close();toast('Demo request saved. Respond through Supplier desk.');navigate('requests');};}
function renderRequests(){main.innerHTML=`<div class="pagehead"><div><div class="eyebrow">BUYER WORKSPACE</div><h1>My requests</h1><p class="muted">Track supplier responses and choose an offer.</p></div><button class="primary" id="new-request">+ New request</button></div>${!db.requests.length?'<div class="empty"><h3>Your first quote starts here.</h3><p>Describe your requirements and request a quote from a matching supplier.</p></div>':db.requests.map(q=>`<article class="request-card"><div class="row spread"><h2>${categories[q.category].name} · ${q.quantity} ${categories[q.category].unit}</h2><span class="small">${esc(q.date)} · ${esc(q.location)}</span></div><p>${esc(q.brief)}</p><div class="chips">${Object.entries(q.specs).map(([,v])=>'<span class="chip">'+esc(v)+'</span>').join('')}</div>${q.notes?'<p class="small">Other requirements: '+esc(q.notes)+'</p>':''}<p class="small">Requested by ${esc(q.customer)} · Budget ${q.budget?money(Number(q.budget)):'not specified'}</p><div class="offers">${db.offers.filter(o=>o.requestId===q.id).map(o=>{const s=db.suppliers.find(x=>x.id===o.supplierId);return `<div class="offer-row"><div><strong>${esc(s.name)}</strong> ${badge(o.status)}<p class="small">${o.total?money(o.total)+' confirmed offer · v'+o.version:money(o.estimate)+' catalog estimate'}${o.expires?' · Valid through '+esc(o.expires):''}</p></div><div class="row"><button class="button-small" data-offer="${o.id}">View ${o.version?'offer':'request'}</button>${canAccept(o)&&!db.offers.some(a=>a.requestId===q.id&&a.status==='Approved')?`<button class="primary button-small" data-approve="${o.id}">Accept offer</button>`:''}<button class="textbutton" data-desk="${o.supplierId}">Open supplier desk</button></div></div>`;}).join('')}</div><div class="row" style="margin-top:13px"><button class="textbutton" data-rematch="${q.id}">Find more suppliers for this request →</button></div></article>`).join('')}`;$('new-request').onclick=()=>navigate('discover');main.querySelectorAll('[data-offer]').forEach(b=>b.onclick=()=>viewOffer(b.dataset.offer));main.querySelectorAll('[data-approve]').forEach(b=>b.onclick=()=>approve(b.dataset.approve));main.querySelectorAll('[data-desk]').forEach(b=>b.onclick=()=>{supplierId=b.dataset.desk;navigate('supplier');});main.querySelectorAll('[data-rematch]').forEach(b=>b.onclick=()=>{const q=db.requests.find(x=>x.id===b.dataset.rematch);request=structuredClone(q);results=null;selected.clear();navigate('discover');});}
function viewOffer(id){const o=db.offers.find(x=>x.id===id),q=db.requests.find(x=>x.id===o.requestId),s=db.suppliers.find(x=>x.id===o.supplierId);open(s.name+' · '+(o.version?'quotation v'+o.version:'request'),`<p>${badge(o.status)}</p><p>${esc(q.brief)}</p><p class="small">${esc(q.date)} · ${esc(q.location)} · ${esc(q.customer)}</p>${q.notes?'<p class="small">Other requirements: '+esc(q.notes)+'</p>':''}<hr class="separator"><h2>${o.total?money(o.total):money(o.estimate)}</h2><p class="small">${o.total?'Supplier-entered service total':'Unconfirmed catalog estimate'}${o.deposit?' · Refundable deposit '+money(o.deposit)+' separate':''}</p>${o.expires?'<p class="small">Valid through '+esc(o.expires)+'</p>':''}<p style="white-space:pre-wrap;margin-top:16px">${esc(o.terms||'Waiting for supplier confirmation of requirements, price, and availability.')}</p>${o.status==='Approved'?'<div class="approval">Accepted version '+o.approvedVersion+' on '+esc(new Date(o.approvedAt).toLocaleString())+'. Payment and fulfillment are arranged directly. This demo sends no messages.</div>':''}${o.history.length?'<details><summary>Previous versions ('+o.history.length+')</summary>'+o.history.map(h=>'<p class="small">v'+h.version+' · '+money(h.total)+' · valid through '+esc(h.expires)+'<br>'+esc(h.terms)+'</p>').join('')+'</details>':''}<div class="dialogactions"><button id="print-offer">Print / save PDF</button>${o.status==='Quoted'?'<button id="revise-offer">Request revision</button>':''}<button data-action="close">Close</button></div>`);$('print-offer').onclick=()=>window.print();if($('revise-offer'))$('revise-offer').onclick=()=>{open('Request a revision',`<form id="revision-form"><div class="field"><label for="revision">What should change?</label><textarea id="revision" required maxlength="2000"></textarea></div><div class="dialogactions"><button type="button" data-action="close">Cancel</button><button class="primary">Save revision request</button></div></form>`);$('revision-form').onsubmit=ev=>{ev.preventDefault();const message=$('revision').value.trim();if(!message)return;o.revisionMessage=message;o.status='Revision requested';save();modal.close();renderRequests();toast('Revision request saved in supplier desk.');};};}
function approve(id){const o=db.offers.find(x=>x.id===id);if(!canAccept(o))return toast('This offer is expired or no longer available.');if(db.offers.some(x=>x.requestId===o.requestId&&x.status==='Approved'))return toast('This request already has an accepted offer.');open('Accept quotation version '+o.version+'?',`<p>Accept the supplier’s offer of <strong>${money(o.total)}</strong>${o.deposit?' with a separate refundable deposit of '+money(o.deposit):''}?</p><p class="small">Payment and production or service scheduling remain separate. No payment will be made.</p><div class="dialogactions"><button data-action="close">Cancel</button><button class="primary" id="accept-confirm">Accept this version</button></div>`);$('accept-confirm').onclick=()=>{if(!canAccept(o))return toast('This quotation can no longer be accepted.');o.status='Approved';o.approvedVersion=o.version;o.approvedAt=new Date().toISOString();save();modal.close();renderRequests();toast('Offer accepted in this demo. No payment made.');};}
function renderSupplier(){const s=db.suppliers.find(x=>x.id===supplierId)||db.suppliers[0];supplierId=s.id;const queue=db.offers.filter(x=>x.supplierId===s.id);main.innerHTML=`<div class="pagehead"><div><div class="eyebrow">SUPPLIER WORKSPACE</div><h1>Turn inquiries into offers.</h1><p class="muted">Manage sample pricing and respond to buyer requests.</p></div></div><div class="supplier-layout"><aside class="panel"><div class="field"><label for="supplier-select">Demo supplier</label><select id="supplier-select">${db.suppliers.map(x=>'<option value="'+x.id+'" '+(x.id===supplierId?'selected':'')+'>'+esc(x.name)+' · '+categories[x.category].name+'</option>').join('')}</select></div><hr class="separator"><h3>Catalog settings</h3><div class="settings-meta"><p>${Object.entries(s.options).map(([k,v])=>esc(k)+': '+v.map(esc).join(', ')).join('<br>')}</p><p>Serves ${s.areas.join(', ')}</p></div><form id="supplier-settings"><div class="field"><label for="base-rate">Base rate per ${categories[s.category].unit.replace(/s$/,'')} · PHP</label><input id="base-rate" type="number" min="0.01" step="0.01" value="${s.rate}" required></div><label class="check"><input id="supplier-active" type="checkbox" ${s.active?'checked':''}>Accepting quote requests</label><p class="helper">Changes affect new estimates. Existing requests and offers keep their saved values. Additional print rates and quantity tiers live in js/data.mjs.</p><button class="full" style="margin-top:13px">Save catalog settings</button></form></aside><section><div class="resulthead"><h2>Incoming requests (${queue.length})</h2><span class="small">Shared demo browser storage</span></div>${!queue.length?'<div class="empty"><h3>No requests for this supplier yet.</h3><p>Create one through Find suppliers or choose another demo supplier.</p></div>':queue.map(o=>{const q=db.requests.find(x=>x.id===o.requestId);return `<article class="request-card"><div class="row spread"><h3>${esc(q.customer)} · ${q.quantity} ${categories[q.category].unit}</h3>${badge(o.status)}</div><p>${esc(q.brief)}</p><p class="small">${esc(q.location)} · Needed ${esc(q.date)}${q.contact?' · Contact: '+esc(q.contact):''}</p><div class="chips">${Object.values(q.specs).map(v=>'<span class="chip">'+esc(v)+'</span>').join('')}</div>${q.notes?'<p class="small">Additional requirements: '+esc(q.notes)+'</p>':''}${o.revisionMessage?'<p class="confirm-note">Revision requested: '+esc(o.revisionMessage)+'</p>':''}<p class="small">Original catalog estimate: ${money(o.estimate)}${o.total?' · Latest offer: '+money(o.total):''}</p><div class="row" style="margin-top:15px"><button data-offer="${o.id}">View ${o.version?'offer':'request'}</button>${o.status!=='Approved'?'<button class="primary" data-respond="'+o.id+'">'+(o.version?'Revise quotation':'Prepare quotation')+'</button>':'<span class="small">Accepted version '+o.approvedVersion+' is preserved.</span>'}</div></article>`;}).join('')}</section></div>`;$('supplier-select').onchange=()=>{supplierId=$('supplier-select').value;renderSupplier();};$('supplier-settings').onsubmit=ev=>{ev.preventDefault();const value=Number($('base-rate').value);if(!Number.isFinite(value)||value<=0)return;s.rate=value;s.active=$('supplier-active').checked;save();toast('Sample catalog settings saved.');};main.querySelectorAll('[data-offer]').forEach(b=>b.onclick=()=>viewOffer(b.dataset.offer));main.querySelectorAll('[data-respond]').forEach(b=>b.onclick=()=>respond(b.dataset.respond));}
function respond(id){const o=db.offers.find(x=>x.id===id),q=db.requests.find(x=>x.id===o.requestId);const expiry=new Date(Date.now()+7*86400000).toISOString().slice(0,10);open('Prepare quotation · version '+(o.version+1),`<form id="offer-form" class="offer-form"><p class="small">${esc(q.brief)}</p><div class="twocol"><div class="field"><label for="final-total">Final service total · PHP</label><input id="final-total" required type="number" min="0.01" step="0.01" value="${o.total||o.estimate}"></div><div class="field"><label for="offer-expiry">Valid through</label><input id="offer-expiry" required type="date" value="${expiry}"></div></div><div class="field"><label for="final-terms">Inclusions, exclusions, and payment terms</label><textarea id="final-terms" maxlength="4000" required>${esc(o.terms||'Includes the requested services and specifications. Final total includes applicable taxes and listed service fees. Payment and fulfillment arranged directly.')}</textarea></div>${o.deposit?'<p class="small">Refundable deposit '+money(o.deposit)+' is separate from the service total.</p>':''}<label class="check"><input type="checkbox" id="confirm-availability" required>I confirm requirements and availability for ${esc(q.date)}.</label><div id="offer-error" class="error" role="alert"></div><div class="dialogactions"><button type="button" data-action="close">Cancel</button><button class="primary">Save confirmed demo offer</button></div></form>`);$('offer-form').onsubmit=ev=>{ev.preventDefault();const total=Number($('final-total').value),expires=$('offer-expiry').value,terms=$('final-terms').value.trim();const error=validateOffer(total,expires);if(error||!terms){$('offer-error').textContent=error||'Add the quotation terms.';return;}if(o.version)o.history.push({version:o.version,total:o.total,expires:o.expires,terms:o.terms});o.total=total;o.expires=expires;o.terms=terms;o.status='Quoted';o.version+=1;o.revisionMessage='';o.confirmedAt=new Date().toISOString();save();modal.close();renderSupplier();toast('Confirmed demo offer saved. Review it in My requests.');};}
